import hashlib,re
t=open('.claude/loa/CLAUDE.loa.md').read()
for name in ['process_compliance_never','process_compliance_always']:
    m=re.search(r'<!-- @constraint-generated: start %s \| hash:([0-9a-f]+) -->\n(.*?)<!-- @constraint-generated: end %s -->'%(name,name),t,re.S)
    h,body=m.group(1),m.group(2)
    cands={'body':body,'body_nodo':body.split('\n',1)[1],'strip':body.strip(),'nodo_strip':body.split('\n',1)[1].strip()}
    for k,v in cands.items():
        for alg in ['sha256','md5','sha1']:
            d=hashlib.new(alg,v.encode()).hexdigest()
            if d.startswith(h): print(name,k,alg,'MATCH')
    print(name,h)
EOF
